/* Spanish profile text (draft, needs review by a fluent reader), keyed by saint id.
 * Missing entries fall back to English. */
window.SAINTS_ES = {
 "aelred-of-rievaulx": {
  "name": "Elredo de Rieval",
  "bio": "Monje cisterciense inglés y abad del monasterio de Rievaulx, que consideraba la amistad humana profunda como un elemento esencial de la vida espiritual y de la cercanía a Dios."
 },
 "alexandrian-washerwoman": {
  "name": "Lavandera alejandrina",
  "bio": "Para los padres y madres del desierto, fundadores del monacato en los siglos IV y V, una mujer anónima y sencilla que oraba sin cesar mientras trabajaba representa la santidad de todo lo ordinario y cotidiano."
 },
 "dante-alighieri": {
  "bio": "Poeta florentino cuya monumental obra en tres partes, <em>La Divina Comedia</em>, nos lleva en el viaje de su alma. Comienza vagando ciego y desesperado en el <em>Infierno</em> y concluye en el <em>Paraíso</em> con una visión extraordinaria de los santos danzantes que rodean «el amor que mueve el sol y las demás estrellas»."
 },
 "roland-allen": {
  "bio": "Misionero anglicano en África oriental que se convirtió en un desafiante y profético crítico del orden establecido, buscando cambiar radicalmente el sistema colonial y paternalista de gobierno de las misiones. Quería restaurar el modelo que veía en la obra misionera del apóstol Pablo: predicar la Buena Nueva, formar pronto líderes locales, confiarles el poder y seguir adelante."
 },
 "thomas-aquinas": {
  "name": "Tomás de Aquino",
  "bio": "Tomás de Aquino estaba convencido de la bondad de toda la creación y de su participación en la bondad del propio ser de Dios. Llamado «el doctor angélico» por su brillante síntesis de fe y razón, está entre los maestros de toda la Iglesia que Dante vio danzando ante Dios en su visión final del <em>Paraíso</em>."
 },
 "barnabas": {
  "name": "Bernabé",
  "bio": "Judío levita, hombre culto y generoso, y uno de los primeros apóstoles después de la resurrección, profundamente respetado por los discípulos. Su confianza en la autenticidad de la conversión de Pablo hizo que aceptaran a este antiguo perseguidor. Fue el primer apóstol en acoger las señales de la gracia de Dios en los corazones de los conversos gentiles al Camino."
 },
 "black-elk": {
  "name": "Alce Negro (Black Elk)",
  "bio": "Hombre santo de los sioux oglala, visionario y místico. Convertido en su juventud, fue instruido por episcopales y se hizo católico romano; con su vida y su enseñanza mostró la presencia radiante y sanadora de Dios en toda la naturaleza."
 },
 "william-blake": {
  "bio": "Artesano de clase obrera que trabajó como grabador, aislado de la cultura dominante, Blake ha resultado ser uno de nuestros mayores humanistas y uno de los artistas más imaginativos, tanto en la pintura como en el grabado. Clamó contra el costo humano de la revolución industrial en Inglaterra, llegó a adorar a Jesús con todo su ser y buscó la unión con Dios a través de su vida y su obra creativa."
 },
 "william-byrd": {
  "bio": "Compositor de música para la Iglesia. Creó una tradición profundamente conmovedora de música coral anglicana que sigue inspirando a compositores de música religiosa en San Gregorio y en otros lugares."
 },
 "donaldina-cameron": {
  "bio": "Fundadora de Cameron House en el barrio chino de San Francisco, esta trabajadora social presbiteriana escocesa desafió a las pandillas chinas y a los jefes del crimen, a la policía corrupta y a los políticos complacientes para rescatar a niñas secuestradas en China y traídas a San Francisco para ser vendidas como prostitutas y esclavas."
 },
 "bartolome-de-las-casas": {
  "bio": "Joven aventurero español que acompañó a Colón en su segundo viaje; recibió grandes extensiones de tierra en el Nuevo Mundo y esclavos indígenas. Lo conmovió tanto su sufrimiento que se hizo sacerdote y liberó a sus esclavos. Fue el primer teólogo cristiano en sostener que esclavizar a otros seres humanos era pecado, siempre y en cualquier circunstancia."
 },
 "christine-de-pisan": {
  "name": "Cristina de Pizán",
  "bio": "Escritora francesa y madre soltera cuya ingeniosa polémica teológica, que se burlaba de las actitudes del clero hacia las mujeres, fue el primer escrito de su tipo al alcance de un público amplio."
 },
 "john-coltrane": {
  "bio": "Saxofonista, compositor y eminente innovador del jazz afroamericano. La fe de Coltrane en Dios fue una poderosa fuerza sanadora para superar su adicción a la heroína. Su álbum fundamental, <em>A Love Supreme</em>, da testimonio de la omnipotencia de Dios y de su poder para rehacernos. Dedicó su música a Dios, diciendo: «Cantemos todas las canciones a Dios»."
 },
 "charles-darwin": {
  "bio": "Naturalista inglés cuyos escritos ofrecieron una comprensión evolutiva del desarrollo de la vida en la tierra, desafiando las interpretaciones convencionales de la creación e invitando a maneras completamente nuevas de pensar en los seres vivos, la humanidad y Dios a través del proceso, el sistema y el cambio. Darwin fue diácono de la Iglesia de Inglaterra."
 },
 "david": {
  "bio": "Guerrillero, rey despótico, asesino de Urías, autor de salmos. Su hijo Salomón reunió a eruditos para crear la primera colección sistemática de los textos sagrados que llegarían a ser la Biblia. Honramos a este personaje complejo y contradictorio por la devoción sencilla y clara de su Salmo 23 y por su alegría desvergonzada al danzar desnudo ante el Arca de Dios."
 },
 "w-edwards-deming": {
  "bio": "Estadístico estadounidense que creía profundamente en la capacidad de las personas para transformarse a sí mismas y a las organizaciones en las que trabajan y viven. Su Movimiento de la Calidad se aplicó primero en el Japón devastado por la guerra. Después de muchos años, la comunidad empresarial e industrial estadounidense finalmente adoptó su trabajo."
 },
 "emily-dickinson": {
  "bio": "Poeta lírica estadounidense cuyas formas austeras y depuradas, sus ritmos casi de jazz y su voz ferozmente personal influyeron enormemente en la poesía moderna. Criada en una familia puritana cuando el trascendentalismo cobraba fuerza, se negó expresamente a hacer una declaración de fe en la universidad y dejó de ir a la iglesia al retirarse de la vida pública. Pero gran parte de su obra giró en torno a su apasionada lucha con Dios."
 },
 "fyodor-dostoievski": {
  "name": "Fiódor Dostoievski",
  "bio": "Novelista y místico ruso que llegó a la fe mientras estaba encarcelado por sus escritos revolucionarios de juventud. Escribió proféticamente sobre el derramamiento de sangre que los principistas «amantes de la humanidad» causarían en el mundo al rechazar el amor de Dios expresado a través de las personas. Su visión de la bondad fundamental de la gente común lo llevó a esperar la salvación universal."
 },
 "elizabeth-i": {
  "name": "Isabel I",
  "bio": "Reina de Inglaterra. Isabel concibió una Iglesia en la que personas de creencias, opiniones y doctrinas diversas pudieran ser una sola mediante la oración y la Eucaristía compartidas. Usó su poder para forjar la paz religiosa sobre este nuevo principio."
 },
 "paul-erdos": {
  "bio": "Erdős vivió como un ángel matemático itinerante, viajando sin cesar y apareciendo de improviso en la puerta de otros matemáticos cuando se encontraban atascados mientras desarrollaban nuevas y apasionantes teorías. Erdős se quedaba el tiempo suficiente para ayudar a encontrar una salida a la dificultad, y luego seguía hacia la siguiente persona que necesitaba una mano."
 },
 "ella-fitzgerald": {
  "bio": "Cantante estadounidense que superó una infancia atormentada, con pobreza extrema y un tiempo en la prostitución, hasta convertirse en una cantante de enorme gracia y alegría."
 },
 "francis-of-assisi": {
  "name": "Francisco de Asís (con lobo)",
  "bio": "Místico italiano y reformador de la Iglesia que cantó la obra de Dios en toda la naturaleza y en la pasión de Cristo. Sus himnos en lengua vulgar, sus procesiones populares y el primer belén de Navidad estuvieron entre sus reformas, que despertaban la imaginación, la esperanza y la alegría de la gente. Siguiendo una historia sobre cómo hizo las paces con los animales, Francisco aparece pintado con un lobo."
 },
 "anne-frank": {
  "name": "Ana Frank",
  "bio": "Joven judía alemana cuyo extraordinario diario, escrito mientras se escondía de los nazis, expresó una fe inquebrantable en la bondad fundamental de la humanidad, sus miedos y frustraciones sin disculpas con las personas con quienes vivía encerrada, sus anhelos y deseos y su gran esperanza en un futuro que sabía que tal vez nunca vería."
 },
 "caspar-david-friedrich": {
  "bio": "Pintor romántico alemán cuyos imponentes paisajes y marinas expresan la profunda presencia mística de Dios en el lado oscuro de la existencia."
 },
 "mohandas-karamchand-gandhi": {
  "bio": "Líder espiritual indio y mártir; activista por la paz y la reconciliación entre musulmanes e hindúes. Inspirado por el Sermón del Monte de Jesús, este maestro hindú de la paz se enfrentó al Imperio británico para liberar a la India por medio de un conflicto moral no violento."
 },
 "martha-graham": {
  "bio": "Martha Graham hizo enormes aportes a la danza moderna y habló de ella en términos claramente místicos. Como bailarina, refutó la idea de que la alegría de bailar debía reservarse a los jóvenes, y siguió coreografiando e interpretando obras liberadoras, llenas de matices y significativas hasta bien entrados sus ochenta años."
 },
 "gregory-of-nyssa": {
  "name": "Gregorio de Nisa",
  "bio": "Obispo y teólogo, nuestro patrono, que dijo: «Esta es la verdadera perfección: no evitar una vida perversa por miedo al castigo, como esclavos; no hacer el bien porque esperamos una recompensa, como si cobráramos la vida virtuosa mediante algún negocio. Por el contrario, sin tener en cuenta todos esos bienes que esperamos y que Dios nos ha prometido, consideramos que perder la amistad de Dios es lo único temible, y que llegar a ser amigos de Dios es lo único que verdaderamente vale la pena»."
 },
 "abraham-joshua-heschel": {
  "bio": "Teólogo y filósofo nacido en Polonia y formado en Alemania. Deportado por los nazis en 1938, llegó al Seminario Teológico Judío de Nueva York, donde enseñó hasta su muerte. Trabajó para revivir las dimensiones mística, profética y activa de la piedad y la práctica judías, destacando la experiencia y la respuesta personal viva en la espiritualidad. Fue un líder en la lucha por los derechos civiles en Estados Unidos y en el activismo contra la guerra."
 },
 "anne-hutchinson": {
  "bio": "Maestra y teóloga puritana inglesa que fue desterrada de la colonia de la bahía de Massachusetts por enseñar que Dios podía ser conocido por la intuición y la experiencia. Después, ella y su esposo se unieron a Roger Williams en Rhode Island y ayudaron a fundar una comunidad abierta a la libertad de conciencia."
 },
 "hypatia": {
  "name": "Hipatia",
  "bio": "Matemática y filósofa pagana que atraía alumnos de todo el mundo griego. Cirilo, arzobispo de Alejandría, la vio como una amenaza para la Iglesia, y fue martirizada a manos de monjes cristianos. Honramos el saber y el valor de Hipatia, y la tenemos como testigo de la curiosidad intelectual y la búsqueda honesta."
 },
 "isaiah": {
  "name": "Isaías",
  "bio": "Profeta hebreo del exilio que habla de nuestro mundo no como un «tocón cortado», sino como algo que «brota de nuevo del tronco de Jesé». Su profecía de Emanuel habla de Dios cerca de nosotros: el espíritu de sabiduría y entendimiento, de consejo y de poder."
 },
 "esther-john": {
  "name": "Esther John (Qamar Zia)",
  "bio": "Maestra y misionera entre las mujeres de la India; se convirtió al cristianismo al leer el capítulo 53 de Isaías. Mantuvo su fe en secreto, pero finalmente huyó de su casa por miedo a que su familia la obligara a casarse con un esposo musulmán. Trabajó en un hospital misionero y evangelizó en las aldeas cercanas, enseñando a leer a las mujeres y trabajando con ellas en los campos de algodón. Fue hallada asesinada en su cama."
 },
 "john-xxiii": {
  "name": "Juan XXIII",
  "bio": "El papa responsable de que el Concilio Vaticano II «abriera las ventanas» para dejar entrar aire fresco en la Iglesia católica. Reunió a eruditos, liturgistas y teólogos, invitándolos a ofrecer su mejor trabajo para el bien de todos."
 },
 "julian-of-norwich": {
  "name": "Juliana de Norwich",
  "bio": "Mística, anacoreta y directora espiritual inglesa, autora de <em>Revelaciones del amor divino</em>. Aunque vivió en medio de los horrores de la peste negra, las visiones sorprendentemente realistas de Juliana sobre los sufrimientos de Jesús en la cruz y sus conversaciones amorosas con él la llevaron a creer las palabras que le oyó decir: «Todo irá bien, y toda clase de cosas irán bien»."
 },
 "kangxi": {
  "bio": "Aunque él mismo no era cristiano, decretó la tolerancia de la fe y la predicación cristianas, construyó iglesias y escribió una conmovedora poesía sobre la pasión de Cristo. Honramos su generosidad de espíritu y oramos para amar y honrar a quienes tienen otra fe o ninguna."
 },
 "lady-godiva": {
  "name": "Lady Godiva (con caballo)",
  "bio": "Según la leyenda, Lady Godiva cabalgó desnuda por las calles de Coventry para protestar contra los impuestos de su esposo, que despojarían a los pobres de todo, incluso de su ropa."
 },
 "li-tim-oi": {
  "bio": "La primera mujer sacerdote de la Comunión Anglicana. Ordenada cuando los británicos huían de Hong Kong durante la Segunda Guerra Mundial, sirvió fielmente durante la ocupación japonesa. Después de la guerra se le negó el sacerdocio, pero entró en China y atendió a toda una generación oculta para Occidente. Más tarde emigró a Canadá, donde fue recibida con honor por su servicio pionero."
 },
 "liliuokalani": {
  "bio": "Anglicana devota, compositora de himnos y pacifista, reinó como la última reina de Hawái entre 1891 y 1893. Fue depuesta por colonos, mantenida bajo arresto domiciliario en su propio palacio y condenada por traición. Durante su encierro solo tenía para leer la Biblia y el libro de oración, y ambos influyeron en la gran obra musical que compuso."
 },
 "nellie-dorothy-lincoln": {
  "name": "Nellie y Dorothy Lincoln",
  "bio": "Nellie Lincoln (1862–1956) y su esposo, el reverendo James O. Lincoln, fundaron un campamento para niños con enfermedades crónicas y potencialmente mortales en memoria de su hija Dorothy, que murió en la infancia. St. Dorothy’s Rest, en el norte de California, lleva su nombre y el de la santa del siglo II, y acoge retiros de iglesias y organizaciones sin fines de lucro, además de campamentos de verano."
 },
 "martin-luther": {
  "name": "Martín Lutero",
  "bio": "Lutero fue un teólogo y maestro espiritual que valoraba la experiencia y los sentimientos como un camino para conocer a Dios. Sus escritos teológicos y litúrgicos muestran a un hombre maravillosamente desprotegido en la oración y en la «batalla con el diablo»."
 },
 "janani-luwum": {
  "bio": "Luwum fue arzobispo de Uganda, Ruanda, Burundi y Boga-Zaire durante el brutal régimen de Idi Amin. Impulsó reformas en su iglesia y, en febrero de 1976, entregó a Amin una protesta contra todos los actos de violencia cometidos por la seguridad del Estado. Poco después fue asesinado por el propio Amin o por sus esbirros."
 },
 "malcolm-x": {
  "bio": "Mientras estaba en prisión por robo, Malcolm se unió a la Nación del Islam y se convirtió en un portavoz radical y virulento del movimiento. Peregrinó a La Meca, donde fue transformado por una visión de una sola humanidad que adora a un solo Dios en paz. Repudió el racismo en todas sus formas. Fue asesinado mientras se preparaba para hablar ante la Organización de la Unidad Afroamericana."
 },
 "thurgood-marshall": {
  "bio": "Abogado estadounidense de los derechos civiles y juez de la Corte Suprema. Jurista distinguido cuya pasión por la equidad y la justicia se formó a partir de su conocimiento y experiencia personal del prejuicio y la pobreza. Defendió una interpretación de la ley que hiciera realidad, de manera más perfecta, la visión de la Constitución de una justicia verdaderamente igual para todos."
 },
 "mary-magdalene": {
  "name": "María Magdalena",
  "bio": "La apóstol de los apóstoles. Cuando los demás huyeron, ella permaneció con Jesús durante su crucifixión, fue la primera a quien se apareció después de su resurrección y la enviada a anunciarla."
 },
 "manche-masemola": {
  "bio": "A los 18 años, Manche se unió a una clase de preparación para el bautismo en su África natal. Sus padres se oponían a que se hiciera cristiana; cada vez que volvía de la clase la golpeaban. Al ver que nada podía quebrantar su fe, su familia la azotó hasta matarla. Tal como le había anunciado a su sacerdote, fue bautizada «con su propia sangre»."
 },
 "iqbal-masih": {
  "bio": "Masih fue enviado a tejer alfombras a los cinco años. A los 10 escapó de los comerciantes de alfombras a quienes estaba sometido por deudas y comenzó a hablar en público a otros niños esclavizados, inspirando a miles a escapar de la esclavitud. A los 13 años, unos asesinos, presuntamente contratados por comerciantes de alfombras, lo mataron en Pakistán cuando salía de la iglesia el Domingo de Pascua."
 },
 "margaret-mead": {
  "bio": "Antropóloga, conocida sobre todo por su trabajo sobre el desarrollo de los adolescentes en Samoa. La influencia de Mead llegó también a la Iglesia Episcopal. Como autoridad en ritos de paso, ayudó a redactar partes del Libro de Oración Común de 1979 sobre el bautismo y la confirmación, y defendió conservar los antiguos relatos de la Vigilia Pascual por su poder para crear un ritual vivo."
 },
 "thomas-merton": {
  "bio": "Monje trapense estadounidense que impulsó la oración y el diálogo interreligiosos, y cuyos escritos han llevado a miles de personas a la práctica de la oración contemplativa."
 },
 "mirabai": {
  "bio": "Poeta medieval del norte de la India. Tras negarse a arrojarse a la pira funeraria de su esposo, emprendió una vida errante, dando la espalda a las convenciones y consagrándose al dios hindú Giridhara. Sus poemas expresan con intensidad la sublimidad de la unión mística con lo divino y la desesperación anhelante por su pérdida: un anhelo tan poderoso que se convierte en señal de la presencia del Amado."
 },
 "miriam": {
  "name": "Miriam",
  "bio": "Hermana mayor de Moisés, considerada la verdadera voz detrás de uno de los poemas más antiguos de las Escrituras hebreas, el <em>Cántico de Moisés</em>, que celebra el hecho, antes inimaginable, de que Dios se pusiera del lado de los esclavos y los condujera a la libertad. En el <em>Éxodo</em>, Miriam guía a las mujeres de Israel en una danza de acción de gracias por la libertad que Dios les ha dado."
 },
 "julia-morgan": {
  "bio": "Arquitecta pionera que tuvo un profundo impacto en el oeste de Estados Unidos. Su concepto del espacio sagrado influyó en el diseño de muchos edificios, incluida la Iglesia de San Gregorio. Buscó contratos con empeño, a veces ofreciendo sus servicios gratis, para construir hermosos espacios públicos, entre ellos la Neighborhood House de Potrero Hill."
 },
 "moses-the-black": {
  "name": "Moisés el Negro",
  "bio": "Ladrón y jefe de banda etíope que vivió una conversión y llegó a ser uno de los más venerados Padres del Desierto, fundadores del monacato."
 },
 "john-muir": {
  "bio": "Padre del movimiento ambientalista moderno. A pesar de una educación religiosa abusiva, siguió siendo un hombre profundamente espiritual y un elocuente portavoz de nuestra sagrada responsabilidad de cuidar la tierra. Dijo: «En lo salvaje está la preservación del mundo»."
 },
 "john-mason-neale": {
  "bio": "Sacerdote anglicano que fundó una de las primeras órdenes anglicanas de mujeres después de la Reforma (las Hermanas de Santa Margarita) para el trabajo de enfermería. Insistió en la formación profesional de las enfermeras y fomentó el liderazgo autónomo de las mujeres en su comunidad. Forjando fuertes lazos ecuménicos con la ortodoxia oriental, aportó un sentido renovado y audaz de belleza y ternura a la liturgia, la himnodia y la arquitectura anglicanas."
 },
 "florence-nightingale": {
  "bio": "Unitaria, en algún momento anglicana, acusada de tener «creencias religiosas eclécticas». Figura principal en el desarrollo de la enfermería moderna gracias a su labor pionera en la guerra de Crimea, reclutó y formó a mujeres para servir en lugares de enfermedad y violencia a los que, según la sensibilidad victoriana, «las damas delicadas no debían ir». Entre sus reclutas había hermanas enfermeras anglicanas de las Hermanas de Santa Margarita."
 },
 "origen": {
  "name": "Orígenes",
  "bio": "Teólogo y maestro alejandrino cuyas homilías influyeron profundamente en Gregorio de Nisa. Orígenes estableció el modelo del comentario bíblico para la teología cristiana."
 },
 "patrick-of-ireland": {
  "name": "Patricio de Irlanda",
  "bio": "En una época de colapso cultural, la obra misionera de Patricio entre los irlandeses fue humanista, pacificadora y generosa. Él y sus colaboradores crearon un cristianismo celta que acogió la antigua reverencia por la naturaleza mientras suprimía prácticas como el sacrificio humano, y que usó el espíritu del bardo viajero de la antigua espiritualidad celta para domar la tradición del héroe guerrero errante."
 },
 "paul-of-tarsus": {
  "name": "Pablo de Tarso",
  "bio": "Autor de casi la mitad del Nuevo Testamento. Pablo se esforzó en sus escritos por expresar su asombrosa visión del abrazo sin reservas de Dios a toda la humanidad en Cristo. Dijo: «Dios estaba en Cristo reconciliando al mundo consigo mismo, no tomando en cuenta a las personas sus pecados ni sus faltas, y nos confió la noticia de que las personas están reconciliadas»."
 },
 "paulos-mar-gregorios": {
  "bio": "Teólogo visionario, obispo y biógrafo de su homónimo, Gregorio de Nisa; llevó la sabiduría de su herencia al movimiento ecuménico. Fue uno de los líderes más creativos e influyentes del Consejo Mundial de Iglesias en sus primeros años. Escribió: «Cuando trabajamos por la unidad de la humanidad, nos apoyamos en nuestras propias convicciones y tradiciones, mientras compartimos una gran visión de Dios en el centro de todo»."
 },
 "norman-perrin": {
  "bio": "Estudioso estadounidense de los Evangelios que desarrolló nuevos principios para recuperar la probable enseñanza original de Jesús en las parábolas. Sostuvo que el testimonio central y audaz de Jesús fue la comida sagrada que compartía con «pecadores no preparados», la señal que imitamos en San Gregorio al invitar a todos a compartir la Eucaristía."
 },
 "marguerite-de-porete": {
  "name": "Margarita Porete",
  "bio": "Mística francesa y autora de <em>El espejo de las almas simples</em>. Acusada de la herejía del «Libre Espíritu», guardó un silencio desdeñoso ante la Inquisición y fue quemada en la hoguera en París."
 },
 "jenny-read": {
  "bio": "Joven escultora episcopal de San Francisco, con dones artísticos y una mente inquieta tanto intelectual como espiritualmente, que fue violada y asesinada mientras trabajaba en una escultura de San Juan de la Cruz."
 },
 "eleanor-roosevelt": {
  "bio": "Mujer privilegiada que, como primera dama, eligió acercarse al sufrimiento, viendo y escuchando la experiencia de las personas pobres o desposeídas para ensanchar su compasión. Usó su acceso al poder político como medio para ofrecerles dignidad y alivio."
 },
 "andrei-rublev": {
  "name": "Andréi Rubliov",
  "bio": "Monje e iconógrafo ortodoxo ruso. Trabajó como ayudante y discípulo de Teófanes el Griego, y con el tiempo pintó imágenes para la oración que unieron la obra de Teófanes con tradiciones populares rusas depuradas, creando una iconografía íntima y humana."
 },
 "jalal-ad-din-rumi": {
  "name": "Yalal ad-Din Rumi",
  "bio": "Poeta místico sufí persa apreciado por cristianos, judíos, musulmanes y no creyentes, en su tiempo y en el nuestro, por su impactante expresión de la presencia de Dios en el éxtasis y en lo cotidiano. Como maestro, invitaba a otros a la unión mística con Dios por medio de la poesía y la danza. Creó la danza giratoria y meditativa de la orden sufí mevleví."
 },
 "sadi": {
  "name": "Sadi (con tigre)",
  "bio": "Poeta persa medieval cuyos <em>Gulistán (El jardín de rosas)</em> y <em>Bustán (El huerto)</em> son clásicos de la literatura mística sufí. Su obra incluye la parábola del zorro herido alimentado por el tigre, y aparece representado con un tigre. Sadi y otros tres santos retratados con animales nos recuerdan que la obra creadora de Dios se extiende a todas las criaturas, y que algunas personas han conocido a Dios en compañía de los animales o mediante una reflexión imaginativa y compasiva sobre sus historias."
 },
 "agnes-sanford": {
  "bio": "Laica episcopal estadounidense que, casi sin ayuda, restauró la práctica de la oración de sanación en las iglesias tradicionales."
 },
 "samuel-isaac-joseph-schereschewsky": {
  "bio": "Schereschewsky fue enviado a China para ser obispo de Shanghái, pero al desembarcar enfermó de una fiebre que lo dejó paralizado. Sin poder cumplir su misión original, el obispo Schereschewsky dedicó el resto de su vida a traducir la Biblia al chino. Lo honramos por su perseverancia ante la tragedia y la limitación —declaró: «Nunca habría podido hacer mi trabajo de no ser por la enfermedad y la silla de ruedas»— y celebramos que encontrara una manera inesperada de cumplir su misión de llevar la Palabra a su nuevo pueblo."
 },
 "seraphim": {
  "name": "Serafín (con oso)",
  "bio": "Místico ortodoxo ruso de la alegría, cuyo amor por todas las criaturas de Dios lo llevó a compartir sus raciones de ayuno con un oso (con el que aparece representado), diciendo: «El pobre oso no puede saber que es Cuaresma»."
 },
 "sergius-bacchus": {
  "name": "Sergio y Baco",
  "bio": "Soldados romanos martirizados por su fe cristiana. La antigua veneración de estos dos hombres muestra cómo la Iglesia honra a dos personas del mismo sexo en una relación de amor. En su amor encontraron valor para la decisión a la que fueron llamados como testigos de Cristo."
 },
 "william-shakespeare": {
  "bio": "Dramaturgo y poeta isabelino profundamente espiritual. Lo celebramos especialmente por su comprensión de la obra de la gracia y de la dinámica de la redención."
 },
 "su-shi": {
  "bio": "Poeta, pintor y funcionario del gobierno chino. Seguidor del budismo chan (zen) y de la Tierra Pura, insistió en hacer buenas obras, incluso durante sus épocas de exilio. Sus políticas de gobierno benéficas influyeron en la creación del New Deal de Franklin D. Roosevelt."
 },
 "maria-skobtsova": {
  "name": "María Skobtsova",
  "bio": "Mujer divorciada que se hizo monja, trabajó con los pobres en Francia y fue martirizada por los nazis por esconder judíos. Era franca, práctica y de un humor atrevido. El metropolita Antonio Bloom contó que, siendo un joven sacerdote, «entonces me ofendía que le gustara sentarse en los bistrós de París con su hábito de monja, fumando cigarrillos, bebiendo cerveza y conversando con trabajadores sencillos. Me avergüenza decir que guardé distancia de esa mujer porque hacía exactamente lo que hizo Cristo»."
 },
 "sorghoqtani": {
  "bio": "Madre de Kublai Kan, así como de otro kan de China y de uno de Persia; mantuvo un hogar cristiano e hizo educar a sus hijos por sacerdotes. Aunque ninguno de sus hijos profesó el cristianismo, fueron amistosos con los cristianos. Su contemporáneo ortodoxo sirio, Gregorio Bar-Hebraeus, atesoró su memoria y dijo: «Era cristiana, sincera y verdadera»."
 },
 "chiune-sugihara": {
  "bio": "Diplomático japonés en Lituania durante la Segunda Guerra Mundial que desafió la política de su gobierno y emitió tantos visados como pudo para salvar a miles de judíos que huían del exterminio nazi."
 },
 "symeon": {
  "name": "Simeón",
  "bio": "Monje, místico y poeta del Espíritu Santo. Escuchaba confesiones y daba la absolución siendo laico. A menudo caminaba desnudo, «sin avergonzarse del cuerpo que Cristo redimió»."
 },
 "lucian-tapiedi": {
  "bio": "Durante la invasión japonesa de Papúa, Tapiedi, maestro de la escuela misionera, se quedó con su pueblo, como hicieron muchos de los otros misioneros. Irónicamente, no lo mataron los japoneses; murió a manos de otro papú, un miembro de la tribu orokaiva llamado Hivijapa. Hivijapa se convirtió más tarde al cristianismo y tomó el nombre de Hivijapa Lucian en memoria de su víctima."
 },
 "teresa-of-avila": {
  "name": "Teresa de Ávila",
  "bio": "Mística española que desafió a la Inquisición al acoger a conversos judíos en su comunidad carmelita. Enseñó que desarrollamos nuestra amistad con Dios en las amistades de la vida comunitaria. En su amistad con Juan de la Cruz fue mentora, aguijón, crítica y amiga espiritual. Se ayudaron mutuamente a seguir adelante con una obra exigente a pesar del escrutinio hostil de sus propias comunidades y de la Inquisición."
 },
 "theosebia": {
  "name": "Teosebia",
  "bio": "Esposa de Gregorio de Nisa. Gregorio fue uno de los últimos obispos casados antes de que nuevas leyes eclesiásticas exigieran que los obispos fueran monjes célibes. Cuando Gregorio escribió sobre la esposa y el esposo en unión mística con Cristo, lo hacía desde su propia experiencia del amor conyugal con Teosebia."
 },
 "m-m-thomas": {
  "bio": "Laico de la Iglesia Mar Thoma, Thomas fue un líder ecuménico pionero, presidente en su momento del Comité Central del Consejo Mundial de Iglesias y director del Instituto para el Estudio de la Religión y la Sociedad en Bangalore. Se retiró a su aldea, donde vivió entre la gente y comenzó un comentario bíblico en la lengua local. Murió viajando en tercera clase en un tren desde Madrás."
 },
 "sojourner-truth": {
  "bio": "Antigua esclava, fue una elocuente crítica de la esclavitud y del sexismo, y cautivaba al público con la fuerza y la sencillez de su mensaje de amor y tolerancia cristianos."
 },
 "desmond-mpilo-tutu": {
  "bio": "Tutu fue el primer africano en servir como obispo de Lesoto, obispo de Johannesburgo y arzobispo de Ciudad del Cabo. Galardonado con el Premio Nobel de la Paz en 1984 por su firme resistencia al apartheid, más tarde presidió la Comisión de la Verdad y la Reconciliación de Sudáfrica, aconsejando siempre el perdón en lugar de la venganza por las injusticias pasadas."
 },
 "morihei-ueshiba": {
  "bio": "Ueshiba entendía que la práctica marcial era para la reconciliación y la protección de todas las cosas. Fundó el aikido, «el camino de la reconciliación», que resuelve el conflicto desarmando al atacante sin hacerle daño y evitando herir incluso al «enemigo». Dijo: «Herir a un oponente es herirte a ti mismo»."
 },
 "simone-weil": {
  "bio": "Filóloga clásica y filósofa judía francesa. Arrebatadamente enamorada de Jesucristo, se negó a pedir el bautismo para seguir identificada con un mundo que busca la redención."
 },
 "charles-wesley": {
  "bio": "Sacerdote anglicano, autor de himnos y, con su hermano John, fundador del movimiento metodista en la Iglesia de Inglaterra. Su innovadora misión entre los trabajadores pobres ofendió a las autoridades de la Iglesia y a los creyentes de la rígida estructura de clases de Inglaterra, al enseñar la dignidad real y sacerdotal del cristiano más humilde, con énfasis en el sentimiento y la experiencia."
 },
 "lucy-wright": {
  "bio": "Sucesora de la Madre Ann, fundadora de los shakers; se le atribuye el desarrollo de la danza sagrada coreografiada y el uso de himnos y antífonas en el culto shaker."
 },
 "wang-zhiming": {
  "bio": "Mártir de la Iglesia en China. Educado en escuelas misioneras y ordenado en 1951, Wang fue pastor de los cristianos del condado de Wuding, en Yunnan, su tierra natal. Durante la Revolución Cultural se opuso a las persecuciones ateas de los Guardias Rojos; fue arrestado en 1969 y ejecutado en un mitin masivo en 1973. Es recordado con reverencia en Wuding, donde hoy hay unos 30 000 cristianos y más de 100 lugares de culto."
 }
};
